krpano.action:
	set(lastlot, %1);

	txtadd(jsc, 'eraPick("', get(hotspot[%1].lotcode), '")');
	jscall(get(jsc));
	set(jsc, '');

	set(ttl, '');
	txtadd(ttl, get(hotspot[%1].lotcode));
	copy(layer[info_title].html, ttl);

	set(fdir, '');
	if(hotspot[%1].lotdir != '',
		txtadd(fdir, '
Huong: ', get(hotspot[%1].lotdir), '');
	);

	set(fpri, '');
	if(hotspot[%1].lotprice != '',
		txtadd(fpri, '
Gia: ', get(hotspot[%1].lotprice), ' trieu');
	);

	set(fsta, '');
	if(hotspot[%1].lotstatus == 'con',
		txtadd(fsta, '
CON HANG');
	);
	if(hotspot[%1].lotstatus == 'giu',
		txtadd(fsta, '
GIU CHO');
	);
	if(hotspot[%1].lotstatus == 'ban',
		txtadd(fsta, '
DA BAN');
	);

	set(t, '');
	txtadd(t, 'Dien tich: ', get(hotspot[%1].lotarea), ' m2',
	          get(fdir), get(fpri), get(fsta));
	copy(layer[info_body].html, t);

	set(bh, 128);
	if(fdir != '', inc(bh, 22); );
	if(fpri != '', inc(bh, 22); );
	set(layer[infobox].height, get(bh));

set(bgcolor, 0xFFFFFF);
set(layer[defaultskin_buttons].y, 98);


set(layer[btn_in].visible,       false);  set(layer[btn_in].enabled,       false);
set(layer[btn_out].visible,      false);  set(layer[btn_out].enabled,      false);
set(layer[btn_left].visible,     false);  set(layer[btn_left].enabled,     false);
set(layer[btn_right].visible,    false);  set(layer[btn_right].enabled,    false);
set(layer[btn_up].visible,       false);  set(layer[btn_up].enabled,       false);
set(layer[btn_down].visible,     false);  set(layer[btn_down].enabled,     false);
set(layer[btn_ctrlmode].visible, false);  set(layer[btn_ctrlmode].enabled, false);
set(layer[btn_autorot].visible,  false);  set(layer[btn_autorot].enabled,  false);

set(layer[btn_fs].x, 0);

set(layer[btn_fs].onclick, 'js(eraFS())');
set(layer[defaultskin_buttons].width, 40);
delayedcall(0.4,
	set(view.fovmin, 0.02);
	lookto(0.0, 0.0, 0.7066, smooth(), true, true);
);
delayedcall(1.2, set(layer[hint].visible, true); );
delayedcall(7.0, tween(layer[hint].alpha, 0, 0.6, default, set(layer[hint].visible,false)); );
